arguments.command:
curl -s https://api.linear.app/graphql -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"query":"{ a: __type(name: \"Query\") { fields { name args { name } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['a']['fields']:
    if 'roadmap' in f['name'].lower(): print(f['name'], [a['name'] for a in f['args']])
"

